mapper.select:
select t.ms_id,t.ms_id msId,t.machine_id,t.machine_id machineId,t.staff_name,t.staff_name
staffName,t.status_cd,t.status_cd statusCd,t.face_path,t.face_path
facePath,t.state,t.message,t.community_id,t.community_id communityId,t.staff_id,t.staff_id staffId,
t.create_time createTime
from attendance_staff t
where 1 =1

    and t.ms_id= #{msId}


    and t.machine_id= #{machineId}


    and t.staff_name= #{staffName}


    and t.status_cd= #{statusCd}


    and t.face_path= #{facePath}


    and t.state= #{state}


    and t.message= #{message}


    and t.community_id= #{communityId}


    and t.staff_id= #{staffId}

order by t.create_time desc

    limit #{page}, #{row}

